mapper.select:
select * from (
    select info.*, case when favor.id is not null then 1 else 0 end as hasStared, u.username, u.nickname
    from t_code_share_info info
    left join t_code_share_favorite favor on info.id = favor.codeInfoId and favor.userId=#{userId,jdbcType=BIGINT}
    left join t_user u on u.id = info.userId
) t_code_share_info

    ${ew.sqlSegment}

        AND username LIKE CONCAT('%', #{queryDto.username}, '%')


        AND nickname LIKE CONCAT('%', #{queryDto.nickname}, '%')


ORDER BY createTime DESC
